<template><div><DsPageHeader title="Autores e tipos" subtitle="Cadastro de autores usados nas referências" icon="people"/><DsPageShell>
  <div class="flex justify-between mb-4"><div class="flex gap-2"><DsButton size="sm" :variant="tab==='autores'?'primary':'secondary'" @click="tab='autores'">Autores</DsButton><DsButton size="sm" :variant="tab==='tipos'?'primary':'secondary'" @click="tab='tipos'">Tipos</DsButton></div><DsButton v-if="auth.isAdmin" variant="success" icon="plus" @click="open()">Novo</DsButton></div>
  <DsAlert v-if="error" variant="error">{{error}}</DsAlert><div v-else-if="loading" class="text-center py-8">Carregando...</div><DsTable v-else><template #head><tr><th>Código</th><th>Nome</th><th v-if="tab==='autores'">Abreviação</th><th v-if="tab==='autores'">Tipo</th><th/></tr></template><tr v-for="r in current" :key="r[idKey]"><td>{{r[idKey]}}</td><td>{{r[nameKey]}}</td><td v-if="tab==='autores'">{{r.abreviacao||'-'}}</td><td v-if="tab==='autores'">{{r.tipo||'-'}}</td><td><div v-if="auth.isAdmin" class="flex justify-end gap-2"><DsButton size="sm" variant="secondary" @click="open(r)">Editar</DsButton><DsButton size="sm" variant="danger" @click="remove(r)">Excluir</DsButton></div></td></tr></DsTable>
  </DsPageShell><DsModal v-model="modal" :title="editing?'Editar':'Novo'"><div v-if="tab==='autores'" class="space-y-3"><DsInput v-model="form.nome" label="Nome"/><DsInput v-model="form.abreviacao" label="Abreviação"/><DsSelect v-model="form.codTipo" label="Tipo"><option value="">Sem tipo</option><option v-for="t in tipos" :key="t.codTipo" :value="String(t.codTipo)">{{t.descricao}}</option></DsSelect><DsInput v-model="form.orcid" label="ORCID"/><DsInput v-model="form.pais" label="País"/><DsInput v-model="form.url" label="URL"/></div><DsInput v-else v-model="form.descricao" label="Descrição"/><template #footer><DsButton variant="secondary" @click="modal=false">Cancelar</DsButton><DsButton @click="save">Salvar</DsButton></template></DsModal></div></template>
<script setup lang="ts">definePageMeta({layout:'default'});const api=useApi(),auth=useAuthStore(),swal=useSwal();const tab=ref<'autores'|'tipos'>('autores'),autores=ref<any[]>([]),tipos=ref<any[]>([]),loading=ref(false),error=ref(''),modal=ref(false),editing=ref<any>(null),form=reactive<any>({});const current=computed(()=>tab.value==='autores'?autores.value:tipos.value),idKey=computed(()=>tab.value==='autores'?'codAutor':'codTipo'),nameKey=computed(()=>tab.value==='autores'?'nome':'descricao');function open(r?:any){editing.value=r||null;Object.keys(form).forEach(k=>delete form[k]);if(r)Object.assign(form,r,{codTipo:r.codTipo?String(r.codTipo):''});modal.value=true}async function load(){loading.value=true;error.value='';try{const[a,t]=await Promise.all([api.get<any>('/api/web/cadastros/autores'),api.get<any>('/api/web/cadastros/autores/tipos')]);autores.value=a.data||[];tipos.value=t.data||[]}catch(e){error.value=e instanceof Error?e.message:'Erro ao carregar.'}finally{loading.value=false}}async function save(){try{const base=tab.value==='autores'?'/api/web/cadastros/autores':'/api/web/cadastros/autores/tipos';const body=tab.value==='autores'?{nome:form.nome,abreviacao:form.abreviacao||null,orcid:form.orcid||null,pais:form.pais||null,url:form.url||null,codTipo:form.codTipo?Number(form.codTipo):null}:{descricao:form.descricao};editing.value?await api.put(`${base}/${editing.value[idKey.value]}`,body):await api.post(base,body);modal.value=false;await load();await swal.toast('Registro salvo.')}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao salvar.','error')}}async function remove(r:any){const c=await swal.confirm('Confirmar exclusão',`Excluir "${r[nameKey.value]}"?`);if(!c?.isConfirmed)return;try{const base=tab.value==='autores'?'/api/web/cadastros/autores':'/api/web/cadastros/autores/tipos';await api.del(`${base}/${r[idKey.value]}`);await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao excluir.','error')}}onMounted(load)</script>
